import { AbstractEvent } from './abstract-event';

export class Event1<T1> extends AbstractEvent {
    public addListener(listener: (arg1: T1) => void, context?: any): void {
        this.addListenerNode(listener, context, false);
    }

    public addListenerOnce(listener: (arg1: T1) => void, context?: any): void {
        this.addListenerNode(listener, context, true);
    }

    public removeListener(listener: (arg1: T1) => void): void {
        super.removeListener(listener);
    }

    public dispatch(arg1: T1): void {
        this.state.dispatchEvent(arg1);
    }
}
